import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { initSchema, nowIso, openDatabase, rowToJob, type JobRow } from './db.ts';

const db = openDatabase();
initSchema(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const HEARTBEAT_STALE_MS = 3000;

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (c: Buffer) => chunks.push(c));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isInRange(v: unknown, min: number, max: number): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

function findByKey(key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as JobRow | undefined;
}

function isUniqueViolation(err: unknown): boolean {
  return err instanceof Error && /UNIQUE constraint failed/.test(err.message);
}

function getHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.beat_at < HEARTBEAT_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];

  const rawKey = req.headers['idempotency-key'];
  const key = rawKey === undefined ? undefined : String(rawKey);
  if (key !== undefined && !KEY_RE.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  // Always read the body so the connection stays in a clean state, even when we reject it.
  const bodyText = await readBody(req);
  const contentType = req.headers['content-type'];
  let body: Record<string, unknown> | undefined;

  if (typeof contentType !== 'string' || contentType.split(';')[0]!.trim().toLowerCase() !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(bodyText);
    } catch {
      errors.push({ field: 'body', message: 'body is not valid JSON' });
    }
    if (parsed !== undefined) {
      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
        body = parsed as Record<string, unknown>;
      } else {
        errors.push({ field: 'body', message: 'body must be a JSON object' });
      }
    }
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  if (body) {
    for (const k of Object.keys(body)) {
      if (!ALLOWED_FIELDS.has(k)) errors.push({ field: k, message: 'unknown field' });
    }
    const rawInput = body.input;
    if (typeof rawInput !== 'string' || rawInput.length < 1 || rawInput.length > 1000 || rawInput.trim() === '') {
      errors.push({ field: 'input', message: 'input must be a string of 1 to 1000 characters that is not only whitespace' });
    } else {
      input = rawInput;
    }
    if (body.steps !== undefined) {
      if (isInRange(body.steps, 1, 20)) steps = body.steps as number;
      else errors.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
    }
    if (body.failAttempts !== undefined) {
      if (isInRange(body.failAttempts, 0, 5)) failAttempts = body.failAttempts as number;
      else errors.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
    }
  }

  if (errors.length > 0) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  // Canonical payload with defaults applied, in fixed key order, used for idempotency comparison.
  const payload = JSON.stringify({ input, steps, failAttempts });

  const respondToReplay = (existing: JobRow): void => {
    if (existing.payload === payload) send(res, 200, rowToJob(existing));
    else sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  };

  if (key !== undefined) {
    const existing = findByKey(key);
    if (existing) {
      respondToReplay(existing);
      return;
    }
  }

  const id = randomUUID();
  const now = nowIso();
  try {
    db.prepare(
      `INSERT INTO jobs(id, status, input, steps, fail_attempts, attempts, progress, output, error,
                        idempotency_key, payload, run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?, ?)`,
    ).run(id, input, steps, failAttempts, key ?? null, payload, Date.now(), now, now);
  } catch (err) {
    if (key !== undefined && isUniqueViolation(err)) {
      const existing = findByKey(key);
      if (existing) {
        respondToReplay(existing);
        return;
      }
    }
    throw err;
  }

  const created = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow;
  send(res, 201, rowToJob(created));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  const methodNotAllowed = () => sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${path}.`);

  if (path === '/health') {
    if (method !== 'GET') return methodNotAllowed();
    return getHealth(res);
  }

  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed();
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (path === '/api/jobs') {
    if (method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
      send(res, 200, { jobs: rows.map(rowToJob) });
      return;
    }
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed();
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (method !== 'GET') return methodNotAllowed();
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, rowToJob(row));
  }

  sendError(res, 404, 'not_found', `No route for ${path}.`);
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Fallback: keep-alive connections must not stall shutdown.
  setTimeout(() => process.exit(0), 2000).unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

