import { setTimeout as sleep } from 'node:timers/promises';
import { initSchema, nowIso, openDatabase, type JobRow } from './db.ts';

const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 500;

const db = openDatabase();
initSchema(db);

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

// Heartbeat: lets the server report whether this worker is alive.
const beatStmt = db.prepare(
  'INSERT INTO worker_heartbeat(id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
);
const writeBeat = (): void => {
  beatStmt.run(Date.now());
};
writeBeat();
const heartbeat = setInterval(writeBeat, HEARTBEAT_MS);

// Recovery: attempts interrupted by a previous worker death are redone under the same number.
db.prepare(
  "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_at = ?, updated_at = ? WHERE status = 'running'",
).run(Date.now(), nowIso());

function inTransaction<T>(fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

/** Claims the oldest eligible queued job and marks it running for a new attempt. */
function claimNext(): JobRow | undefined {
  return inTransaction(() => {
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_at <= ? ORDER BY seq ASC LIMIT 1")
      .get(Date.now()) as JobRow | undefined;
    if (!row) return undefined;
    db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ? WHERE id = ?").run(
      nowIso(),
      row.id,
    );
    return { ...row, status: 'running', attempts: row.attempts + 1, progress: 0 };
  });
}

function requeue(id: string, delayMs: number, attempts: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', attempts = ?, progress = 0, run_at = ?, updated_at = ? WHERE id = ?").run(
    attempts,
    Date.now() + delayMs,
    nowIso(),
    id,
  );
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: fails at the first step, before any progress.
  if (attempt <= job.fail_attempts) {
    if (attempt >= MAX_ATTEMPTS) {
      db.prepare(
        "UPDATE jobs SET status = 'failed', error = 'transient failure', output = NULL, progress = 0, updated_at = ? WHERE id = ?",
      ).run(nowIso(), job.id);
    } else {
      requeue(job.id, RETRY_DELAY_MS, attempt);
    }
    return;
  }

  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Hand the job back cleanly; this attempt did not finish, so it does not count.
      requeue(job.id, 0, attempt - 1);
      return;
    }
    db.prepare('UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ?').run(i, nowIso(), job.id);
  }

  db.prepare(
    "UPDATE jobs SET status = 'completed', output = ?, progress = steps, error = NULL, updated_at = ? WHERE id = ?",
  ).run(job.input.toUpperCase(), nowIso(), job.id);
}

console.log('worker started');
while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNext();
  } catch (err) {
    console.error('claim failed:', err);
    await sleep(IDLE_POLL_MS);
    continue;
  }
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (err) {
    console.error(`attempt on job ${job.id} failed:`, err);
  }
}

clearInterval(heartbeat);
db.prepare('DELETE FROM worker_heartbeat WHERE id = 1').run();
db.close();
console.log('worker stopped');
process.exit(0);

