import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { initSchema, nowIso, openDatabase, rowToJob, type JobRow } from './db.ts';

const db = openDatabase();
initSchema(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const HEARTBEAT_STALE_MS = 3000;

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (c: Buffer) => chunks.push(c));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isInRange(v: unknown, min: number, max: number): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

function findByKey(key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as JobRow | undefined;
}

function isUniqueViolation(err: unknown): boolean {
  return err instanceof Error && /UNIQUE constraint failed/.test(err.message);
}

function getHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.beat_at < HEARTBEAT_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];

  const rawKey = req.headers['idempotency-key'];
  const key = rawKey === undefined ? undefined : String(rawKey);
