  const bodyText = await readBody(req);
  const contentType = req.headers['content-type'];
  let body: Record<string, unknown> | undefined;

  if (typeof contentType !== 'string' || contentType.split(';')[0]!.trim().toLowerCase() !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(bodyText);
    } catch {
      errors.push({ field: 'body', message: 'body is not valid JSON' });
    }
    if (parsed !== undefined) {
      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
        body = parsed as Record<string, unknown>;
      } else {
        errors.push({ field: 'body', message: 'body must be a JSON object' });
      }
    }
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  if (body) {
    for (const k of Object.keys(body)) {
      if (!ALLOWED_FIELDS.has(k)) errors.push({ field: k, message: 'unknown field' });
    }
    const rawInput = body.input;
    if (typeof rawInput !== 'string' || rawInput.length < 1 || rawInput.length > 1000 || rawInput.trim() === '') {
      errors.push({ field: 'input', message: 'input must be a string of 1 to 1000 characters that is not only whitespace' });
    } else {
      input = rawInput;
    }
    if (body.steps !== undefined) {
      if (isInRange(body.steps, 1, 20)) steps = body.steps as number;
      else errors.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
    }
    if (body.failAttempts !== undefined) {
      if (isInRange(body.failAttempts, 0, 5)) failAttempts = body.failAttempts as number;
      else errors.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
    }
  }

  if (errors.length > 0) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  // Canonical payload with defaults applied, in fixed key order, used for idempotency comparison.
  const payload = JSON.stringify({ input, steps, failAttempts });

  const respondToReplay = (existing: JobRow): void => {
    if (existing.payload === payload) send(res, 200, rowToJob(existing));
    else sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  };

  if (key !== undefined) {
    const existing = findByKey(key);
    if (existing) {
      respondToReplay(existing);
      return;
    }
  }

  const id = randomUUID();
  const now = nowIso();
  try {
    db.prepare(
      `INSERT INTO jobs(id, status, input, steps, fail_attempts, attempts, progress, output, error,
                        idempotency_key, payload, run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?, ?)`,
    ).run(id, input, steps, failAttempts, key ?? null, payload, Date.now(), now, now);
  } catch (err) {
    if (key !== undefined && isUniqueViolation(err)) {
      const existing = findByKey(key);
      if (existing) {
        respondToReplay(existing);
        return;
      }
    }
    throw err;
  }

  const created = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
  send(res, 201, rowToJob(created));
}

